              status: "reference_mismatch",
              code,
              conflicts: error.details,
              message: "该引用与用户原文明示条件冲突，不能交付。请从历史索引选择同时匹配机构、日期和指标的另一个已有结果；不要创建新任务。"
            }, { kind: "metric_read", status: "reference_mismatch", task_id: params.task_id });
          };
          const message = error.status === 404 ? "任务不存在或无权访问。" : code === "RESULT_NOT_READY" ? "结果尚未就绪，任务还未成功完成。" : code === "RESULT_SNAPSHOT_MISSING" ? "结果快照缺失，无法回放；请重新查询。" : "结果读取暂时失败，请稍后重试。";
          return json(
            { status: "error", error: { code, message } },
